fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // Construct the first matrix: each row is a clone of x
    let x_matrix: Vec<Vec<f32>> = (0..rows)
        .map(|_| x.clone())
        .collect();

    // Construct the second matrix: each row contains the corresponding element of y repeated cols times
    let y_matrix: Vec<Vec<f32>> = y.iter()
        .map(|&val| vec![val; cols])
        .collect();

    (x_matrix, y_matrix)
}